//! MCC U13 names from Assembly's ReachMCC_U13_Scripting.xml, generated by Lord Zedd.
//! The bundled table is a projection of the GPL-3.0 Assembly reference, not runtime bindings.
use super::Node;
use serde::Deserialize;
use std::{collections::BTreeMap, sync::OnceLock};

#[derive(Deserialize)]
pub(super) struct Vocabulary {
    pub functions: BTreeMap<u16, String>,
    pub globals: BTreeMap<u16, String>,
    pub types: BTreeMap<u16, Type>,
}

#[derive(Deserialize)]
pub(super) struct Type {
    pub name: String,
    pub quoted: bool,
    pub tag: Option<String>,
}

pub(super) fn get() -> &'static Vocabulary {
    static TABLE: OnceLock<Vocabulary> = OnceLock::new();
    TABLE.get_or_init(|| {
        serde_json::from_str(include_str!("u13.json")).expect("Bundled MCC U13 script vocabulary")
    })
}

pub(super) fn has_text(node: &Node) -> bool {
    matches!(node.kind(), 13 | 29)
        || (node.kind() == 9
            && (node.value_type == 2
                || get().types.get(&node.literal_type()).is_some_and(|ty| {
                    ty.quoted
                        || matches!(
                            ty.name.as_str(),
                            "string" | "ai_line" | "script" | "ai_command_script"
                        )
                })))
}
